        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401108845, true)
    end,
})

Window:AddButton({
    text = "Scare All",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3450911952, true)
    end,
})

Window:AddToggle({
    text = "Spam Strength",
    flag = "toggle",
    state = false,
    callback = function(state)
        _G.Strength = state
        print("Strength: ", state)
        if state then
            Strength()
        end
    end,
})

function Strength()
    spawn(function()
        _G.Strength = true
        while _G.Strength do
            wait()
            pcall(function()
                game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104590, true)
                wait()
            end)
        end
    end)
end

Window:AddLabel({ text = "YouTube: Tora IsMe" })
Library:Init()
